namespace Shop.Pricing;

public record Item(decimal Price, int Qty);

public static class PriceCalculator
{
    public static decimal CalcTotal(IEnumerable<Item> items, decimal taxRate)
    {
        return (1 + taxRate) * items.Sum(i => i.Price * i.Qty);
    }

    public static string FormatPrice(decimal amount) => amount.ToString("C");
}

